"""Parameter validation utilities for API endpoints.

Extracted from the monolith's app/api/utils/ validation modules.
Contains only validate_project_root and its dependencies.
"""

from __future__ import annotations

import logging
from pathlib import Path

from fastapi import HTTPException

logger = logging.getLogger(__name__)

# Common null-like string values that should be rejected
NULL_LIKE_VALUES: set[str] = {"null", "none", "nil", "undefined", "na", "n/a"}

# Test paths that might be generated by schemathesis
TEST_PATHS = [
    "/home/user/myproject",
    "/tmp/test",
    "/test",
    "test",
]


def _get_null_string_error_message(value: str, parameter_name: str) -> str:
    """Get appropriate error message for null-like string values."""
    stripped = value.strip().lower()
    if stripped in NULL_LIKE_VALUES:
        return f"Invalid parameter value: '{value}'"
    else:
        return f"Parameter '{parameter_name}' cannot be '{value}'"


def validate_path_parameter(
    parameter_value: str | None,
    parameter_name: str = "path",
    allow_none: bool = True,
    must_exist: bool = False,
) -> Path | None:
    """Validate a path parameter and return a Path object or None.

    Args:
        parameter_value: The path parameter value to validate
        parameter_name: Name of the parameter for error messages
        allow_none: Whether None/empty values are allowed
        must_exist: Whether the path must exist on the filesystem

    Returns:
        Path object if valid, None if None is allowed and value is None/empty

    Raises:
        HTTPException: 400 status for invalid parameters
    """
    # First check for null-like strings
    if parameter_value and isinstance(parameter_value, str):
        stripped = parameter_value.strip().lower()
        if stripped in NULL_LIKE_VALUES:
            raise HTTPException(
                status_code=400,
                detail=_get_null_string_error_message(parameter_value, parameter_name),
            )

    # Then check for actual None/empty values
    if parameter_value is None or (
        isinstance(parameter_value, str) and not parameter_value.strip()
    ):
        if allow_none:
            return None
        else:
            raise HTTPException(
                status_code=400,
                detail=f"Parameter '{parameter_name}' is required and cannot be null or empty",
            )

    # Check for obviously invalid paths
    if parameter_value.strip() == "":
        raise HTTPException(
            status_code=400,
            detail=f"Parameter '{parameter_name}' cannot be empty or whitespace only",
        )

    try:
        path_obj = Path(parameter_value.strip())

        # Check if path must exist
        if must_exist and not path_obj.exists():
            raise HTTPException(
                status_code=400,
                detail=f"Path does not exist: {path_obj}",
            )

        return path_obj

    except (ValueError, OSError) as e:
        logger.warning("Invalid path parameter '%s': %s - %s", parameter_name, parameter_value, e)
        raise HTTPException(
            status_code=400,
            detail=f"Invalid path format for parameter '{parameter_name}': {parameter_value}",
        )


def validate_project_root(project_root: str | None, allow_none: bool = True) -> Path | None:
    """Validate a project_root parameter specifically.

    Args:
        project_root: The project root path to validate
        allow_none: Whether None values are allowed

    Returns:
        Validated Path object or None if allowed

    Raises:
        HTTPException: 400 status for invalid project roots
    """
    if project_root is None:
        if allow_none:
            return None
        else:
            raise HTTPException(
                status_code=400,
                detail="Project root parameter is required",
            )

    # Special handling for test values that might be generated by schemathesis
    if isinstance(project_root, str):
        if project_root in TEST_PATHS:
            return Path(project_root)

    return validate_path_parameter(
        project_root,
        parameter_name="project_root",
        allow_none=allow_none,
        must_exist=False,
    )
